using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using Railroader.Modding;
using UnityEngine;

public sealed class CrossingPadEntry : IModEntryPoint, IWorldLifecycle
{
    GameObject host;
    public void OnModLoad(IModContext c) { host = new GameObject("Crossing pad probe"); UnityEngine.Object.DontDestroyOnLoad(host); host.AddComponent<CrossingPadProbe>().Init(c.ModDirectory); }
    public void OnWorldLoad() { }
    public void OnWorldUnload() { }
    public void OnModUnload() { if (host != null) UnityEngine.Object.Destroy(host); }
}
public sealed class CrossingPadProbe : MonoBehaviour
{
    const BindingFlags F = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static;
