    public void Init(string dir) { log = Path.Combine(dir, "CrossingPadProbe.log"); var args=Environment.GetCommandLineArgs(); int first=Array.FindIndex(args, x => string.Equals(x,"-homedir",StringComparison.OrdinalIgnoreCase)); isolated=first >= 0 && first+1 < args.Length && string.Equals(Path.GetFullPath(args[first+1]).TrimEnd(Path.DirectorySeparatorChar), @"C:\TMP\RailroaderMapResearch\RuntimeHome", StringComparison.OrdinalIgnoreCase) && string.Equals(Path.GetFullPath(dir).TrimEnd(Path.DirectorySeparatorChar), @"C:\TMP\RailroaderMapResearch\RuntimeHome\Mods\CrossingPadProbe", StringComparison.OrdinalIgnoreCase); W("loaded isolated=" + isolated); if (!isolated) status="Wrong home or probe directory. Controls disabled."; }
    void CheckWorld() { if (!isolated || Convert.ToString(R(T("Game.ActiveMapDefinition"),"Identifier")) != "crankyant/scene-operations-map" || marker == null || builder == null || graph == null || !marker.gameObject.scene.IsValid() || !marker.gameObject.scene.isLoaded || !ReferenceEquals(R(T("Track.Graph"), "Shared"), graph) || (Origin()-origin).sqrMagnitude >= 0.0001f) throw new InvalidOperationException("World, graph or origin changed; abandon without saving"); }
    void Check() { if (!captured) throw new InvalidOperationException("Complete baseline required"); CheckWorld(); }
    void ResetCapture() { captured=false; marker=null; builder=null; graph=null; old=null; candidate=null; location=null; baseline=null; }
    void Registration(string phase) { var buckets = (IDictionary)R(graph, "_namedLocationsBySegmentId"); int n = 0; foreach (DictionaryEntry bucket in buckets) foreach (DictionaryEntry e in (IDictionary)bucket.Value) if (Convert.ToString(e.Key) == "Mg74") { n++; bool sameMarker = ReferenceEquals(R(e.Value,"ObjectValue"), marker); bool sameLocation = Equals(R(e.Value,"Location"),location.GetValue(marker,null)); W(phase + " registration bucket=" + bucket.Key + " sameMarker=" + sameMarker + " sameLocation=" + sameLocation); if (!sameMarker || !sameLocation || Convert.ToString(bucket.Key) != "Sj7c") throw new InvalidOperationException("Registration mismatch"); } W(phase + " registrations=" + n); if (n != 1) throw new InvalidOperationException("Expected exactly one registration"); }
    string Snapshot(string phase, bool capturing = false)
    {
        if (capturing) CheckWorld(); else Check(); Registration(phase); var signature = new StringBuilder(); var rel = marker.GetComponent(T("Track.TrackRelativePosition")); var target = R(rel,"targetTransform") as Transform;
        var binding = R(marker,"_location"); W(phase + " marker=" + PathOf(marker.transform) + " segment=" + R(binding,"segmentId") + " end=" + R(binding,"end") + " distance=" + R(binding,"distance") + " pose=" + marker.transform.position.ToString("F5") + " target=" + (target == null ? "null" : PathOf(target) + " pos=" + target.position.ToString("F5") + " rot=" + target.rotation.ToString("F5")) + " origin=" + Origin().ToString("F5") + " group=" + R(rel,"_observedGroupId") + " observing=" + R(rel,"_observing"));
        var container = (Transform)R(builder,"meshContainer"); var token = R(builder,"_cullingToken"); W(phase + " builderEnabled=" + ((Behaviour)builder).enabled + " container=" + (container == null ? "null" : PathOf(container)) + " localCenter=" + R(builder,"_boundsCenterLocal") + " radius=" + R(builder,"_boundsRadius") + " token=" + (token == null ? "null" : token.GetHashCode().ToString()));
        if (token == null) throw new InvalidOperationException("Missing culling token"); if (token != null) { var manager = R(token,"Manager"); int index = (int)R(token,"<Index>k__BackingField"); var spheres = (BoundingSphere[])R(manager,"_spheres"); if (index < 0 || index >= spheres.Length || index >= (int)R(manager,"_sphereCount") || (bool)R(token,"<IsRemoved>k__BackingField")) throw new InvalidOperationException("Invalid culling token"); signature.Append(spheres[index].position.ToString("F5")).Append("|").Append(spheres[index].radius.ToString("R")); W(phase + " culler index=" + index + " removed=" + R(token,"<IsRemoved>k__BackingField") + " sphere=" + (index >= 0 && index < spheres.Length ? spheres[index].position.ToString("F5") + " radius=" + spheres[index].radius : "invalid")); }
        if (container == null) throw new InvalidOperationException("Missing mesh container"); var filters = container.GetComponentsInChildren<MeshFilter>(true); if (filters.Length == 0) throw new InvalidOperationException("No generated mesh");
        foreach (var filter in filters) { var mesh = filter.sharedMesh; if (mesh == null) throw new InvalidOperationException("Missing generated mesh"); var verts = mesh.vertices; unchecked { ulong hash = 14695981039346656037UL; foreach (var v in verts) foreach (float f in new[]{v.x,v.y,v.z}) { var b = BitConverter.GetBytes(f); foreach (byte x in b) hash = (hash ^ x) * 1099511628211UL; } signature.Append("|").Append(verts.Length).Append(":").Append(hash.ToString("X16")).Append(":").Append(mesh.bounds.ToString()).Append(":").Append(filter.transform.position.ToString("F5")).Append(":").Append(filter.transform.rotation.ToString("F5")); W(phase + " mesh=" + PathOf(filter.transform) + " object=" + mesh.GetInstanceID() + " vertices=" + verts.Length + " hash=" + hash.ToString("X16") + " bounds=" + mesh.bounds + " transform=" + filter.transform.position.ToString("F5") + " rotation=" + filter.transform.rotation.ToString("F5") + " renderer=" + (filter.GetComponent<Renderer>() == null ? "null" : filter.GetComponent<Renderer>().enabled.ToString())); } }
        return signature.ToString();
    }
    void Capture() { if (!isolated) { status="Wrong home or probe directory."; return; } if (dirty) { status="Restore and verify first; or abandon without saving."; return; } ResetCapture(); try { if (Convert.ToString(R(T("Game.ActiveMapDefinition"),"Identifier")) != "crankyant/scene-operations-map") throw new InvalidOperationException("Wrong map"); var found = Resources.FindObjectsOfTypeAll(T("Track.TrackMarker")).OfType<Component>().Where(c => c.gameObject.scene.IsValid() && c.gameObject.scene.isLoaded && Convert.ToString(R(c,"id")) == "Mg74").ToArray(); if (found.Length != 1) throw new InvalidOperationException("Expected one Mg74"); marker=found[0]; builder=marker.GetComponent(T("Track.TrackCurveMeshBuilder")); if (builder == null || !((Behaviour)marker).enabled || !marker.gameObject.activeInHierarchy) throw new InvalidOperationException("Inactive marker or missing builder"); graph=R(T("Track.Graph"),"Shared"); origin=Origin(); location=marker.GetType().GetProperty("Location",F); old=location.GetValue(marker,null); var serial=R(marker,"_location"); if (Convert.ToString(R(serial,"segmentId")) != "Sj7c") throw new InvalidOperationException("Unexpected segment"); var copy=Activator.CreateInstance(serial.GetType()); foreach (var name in new[]{"segmentId","distance","end"}) { var f=serial.GetType().GetField(name,F); f.SetValue(copy,name == "distance" ? (object)(Convert.ToSingle(f.GetValue(serial))+1f) : f.GetValue(serial)); } var args=new[]{copy,(object)null}; if (!(bool)graph.GetType().GetMethod("TryResolveLocation").Invoke(graph,args) || args[1] == null || args[1].Equals(old)) throw new InvalidOperationException("Candidate invalid"); candidate=args[1]; baseline=Snapshot("baseline", true); captured=true; status="Baseline captured. Rebind, inspect, repeat, restore."; } catch(Exception e) { ResetCapture(); W("capture ERROR " + e); status="Capture failed; inspect log."; } }
    void Set(object value) { ((Behaviour)marker).enabled=false; try { location.SetValue(marker,value,null); } finally { ((Behaviour)marker).enabled=true; } }
    void Rebind() { try { Check(); dirty=true; Set(candidate); Snapshot("rebound"); status="Rebound. Snapshot after settling; inspect visible geometry."; } catch(Exception e) { W("rebind ERROR " + e); status="Failed. Restore or abandon without saving."; } }
    void Observe() { try { Snapshot("observation"); status="Snapshot recorded."; } catch(Exception e) { W("snapshot ERROR " + e); status="Snapshot failed; abandon without saving."; } }
    void Generate() { try { Check(); dirty=true; builder.GetType().GetMethod("Generate",F,null,Type.EmptyTypes,null).Invoke(builder,null); Snapshot("explicit-generate"); status="Native Generate called. Observe and compare with baseline."; } catch(Exception e) { W("generate ERROR " + e); status="Generate failed; abandon without saving."; } }
    void Restore() { try { Check(); Set(old); Snapshot("binding-restored-before-generate"); if (!Equals(location.GetValue(marker,null),old)) throw new InvalidOperationException("Binding restoration mismatch"); status="Binding restored. Generate if needed, then verify restoration."; } catch(Exception e) { W("restore ERROR " + e); status="Restore failed; abandon without saving."; } }
    void Verify() { try { Check(); if (!Equals(location.GetValue(marker,null),old)) throw new InvalidOperationException("Binding differs from baseline"); string current=Snapshot("verify-restoration"); bool matches = current == baseline; W("restoration contentAndSphereMatch=" + matches); if (!matches) throw new InvalidOperationException("Mesh or culling signature differs from baseline"); dirty=false; status="Binding, mesh signature and sphere match. Inspect visual result."; } catch(Exception e) { W("verify ERROR " + e); status="Restoration not verified. Abandon without saving if unresolved."; } }
    void OnGUI() { window=GUI.Window(0x43525044,window,id=>{ GUILayout.Label(status); GUI.enabled = isolated && !dirty; if(GUILayout.Button("Capture Mg74 baseline")) Capture(); GUI.enabled = captured; if(GUILayout.Button("Rebind or repeat +1m")) Rebind(); if(GUILayout.Button("Snapshot current")) Observe(); if(GUILayout.Button("Call native Generate explicitly")) Generate(); if(GUILayout.Button("Restore original binding")) Restore(); if(GUILayout.Button("Verify restoration against baseline")) Verify(); GUI.enabled = true; GUILayout.Label("Disposable world only. Never save. Generated geometry may need reload."); GUI.DragWindow(); },"Crossing pad probe"); }
}
